// Sample messages for the inbox block. Made up; replace with your own.

export type Folder = "inbox" | "drafts" | "sent" | "archive" | "trash";

export type Message = {
  id: string;
  folder: Folder;
  from: string;
  email: string;
  subject: string;
  preview: string;
  body: string[];
  date: string;
  unread: boolean;
  label?: "Work" | "Billing" | "Team";
};

export const FOLDERS: Array<{ id: Folder; label: string }> = [
  { id: "inbox", label: "Inbox" },
  { id: "drafts", label: "Drafts" },
  { id: "sent", label: "Sent" },
  { id: "archive", label: "Archive" },
  { id: "trash", label: "Trash" },
];

export const MESSAGES: Message[] = [
  {
    id: "m1",
    folder: "inbox",
    from: "Wade Warren",
    email: "wade@acme.example",
    subject: "Billing API: rollout plan",
    preview: "I have split the rollout into two steps so we can watch the error rate...",
    body: [
      "Hi Jane,",
      "I have split the rollout into two steps so we can watch the error rate before the second half goes live. The first step moves the read endpoints on Tuesday; writes follow on Thursday if nothing looks off.",
      "Could you check the customer-facing copy for the status page before Monday?",
      "Thanks, Wade",
    ],
    date: "09:42",
    unread: true,
    label: "Work",
  },
  {
    id: "m2",
    folder: "inbox",
    from: "Esther Howard",
    email: "esther@acme.example",
    subject: "Ember beta feedback",
    preview: "The first round of feedback is in. People love the offline mode...",
    body: ["The first round of feedback is in. People love the offline mode, and three testers asked for a dark theme.", "I have grouped the rest by screen in the doc. Shall we go through it on Wednesday?", "Esther"],
    date: "08:15",
    unread: true,
    label: "Team",
  },
  {
    id: "m3",
    folder: "inbox",
    from: "Billing",
    email: "billing@acme.example",
    subject: "Invoice INV-1042 was paid",
    preview: "Jane Cooper paid invoice INV-1042 for $1,280. The payout arrives in...",
    body: ["Jane Cooper paid invoice INV-1042 for $1,280.", "The payout arrives in your bank account within two working days."],
    date: "Yesterday",
    unread: false,
    label: "Billing",
  },
  {
    id: "m4",
    folder: "inbox",
    from: "Brooklyn Simmons",
    email: "brooklyn@acme.example",
    subject: "Beacon onboarding copy",
    preview: "Attached are two versions of the welcome screen. I prefer the shorter...",
    body: ["Attached are two versions of the welcome screen. I prefer the shorter one, but the longer one tested slightly better.", "Your call."],
    date: "Mon",
    unread: false,
    label: "Work",
  },
  {
    id: "m5",
    folder: "inbox",
    from: "Robert Fox",
    email: "robert@acme.example",
    subject: "Fjord analytics kickoff",
    preview: "Kickoff is booked for 9 November. I have shared the brief and the...",
    body: ["Kickoff is booked for 9 November. I have shared the brief and the data access request.", "Let me know if anyone else should join."],
    date: "Sun",
    unread: false,
    label: "Team",
  },
  {
    id: "m6",
    folder: "sent",
    from: "Jane Cooper",
    email: "jane@acme.example",
    subject: "Re: Quarterly review",
    preview: "Thanks all. Notes and next steps are in the shared drive...",
    body: ["Thanks all. Notes and next steps are in the shared drive."],
    date: "Fri",
    unread: false,
  },
  {
    id: "m7",
    folder: "drafts",
    from: "Jane Cooper",
    email: "jane@acme.example",
    subject: "Holiday cover",
    preview: "While I am away from the 20th, Wade will cover reviews...",
    body: ["While I am away from the 20th, Wade will cover reviews for Atlas and Beacon."],
    date: "Thu",
    unread: false,
  },
];

/* Inbox block layout. The panes are one frosted group on the page field. */

.root {
  height: 100dvh;
  padding: 16px;
  background: var(--page-background);
}

.contained {
  height: 100%;
}

.group {
  height: 100%;
}

.folders,
.listPane,
.detail,
.detailEmpty {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-width: 0;
  overflow: hidden;
}

.folders {
  gap: 14px;
  padding: 16px 10px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 6px;
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 700;
  color: var(--ink-heading);
  white-space: nowrap;
}

.glyph {
  display: inline-grid;
  place-items: center;
  flex-shrink: 0;
  width: 26px;
  height: 26px;
  border-radius: var(--r-sm);
  background: var(--brand-gradient);
  font-size: 13px;
  color: var(--ink-inverse);
}

.folderList {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.folder {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 8px 10px;
  border: 0;
  border-radius: var(--r-sm);
  background: transparent;
  font-size: var(--text-small);
  font-weight: 700;
  text-align: left;
  color: var(--ink-secondary);
  transition: background-color var(--dur) var(--ease);
}

.folder:hover {
  background: var(--wash-hover);
}

.folder[aria-current="page"] {
  background: var(--wash-active);
  color: var(--ink-brand);
}

.folder:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.folderLabel {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.listHead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px 10px;
}

.h2 {
  font-size: var(--text-section);
}

.search {
  padding: 0 16px 12px;
  border-bottom: var(--border-w) solid var(--line-glass);
}

.messages {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px;
  overflow-y: auto;
  scrollbar-width: thin;
}

.message {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
  padding: 10px 12px;
  border: 0;
  border-radius: var(--r-md);
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--line-glass);
  text-align: left;
  color: var(--ink-body);
  transition: background-color var(--dur) var(--ease);
}

.message:hover {
  background: var(--wash-hover);
}

.message[aria-current="true"] {
  background: var(--wash-active);
  box-shadow: inset 0 0 0 1px var(--line-brand);
}

.message:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.messageTop {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.from {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--text-small);
  font-weight: 700;
  color: var(--ink-secondary);
}

.unread {
  color: var(--ink-heading);
}

.dot {
  width: 7px;
  height: 7px;
  border-radius: var(--r-full);
  background: var(--brand);
}

.date {
  flex-shrink: 0;
  font-size: var(--text-caption);
  color: var(--ink-muted);
}

.subject {
  font-size: var(--text-small);
  font-weight: 700;
  color: var(--ink-heading);
}

.preview {
  display: -webkit-box;
  overflow: hidden;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  font-size: var(--text-caption);
  color: var(--ink-muted);
}

.detail {
  overflow-y: auto;
}

.toolbar {
  display: flex;
  gap: 4px;
  padding: 10px 12px;
  border-bottom: var(--border-w) solid var(--line-glass);
}

.detailHead {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px 0;
}

.detailMeta {
  flex: 1;
  min-width: 0;
}

.detailFrom {
  font-weight: 700;
  color: var(--ink-heading);
}

.detailEmail {
  font-size: var(--text-caption);
  color: var(--ink-muted);
}

.detailSubject {
  padding: 14px 20px 0;
  font-size: var(--text-card-title);
}

.body {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 12px;
  padding: 12px 20px 20px;
  line-height: 1.65;
  color: var(--ink-body);
}

.reply {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px 20px 18px;
  border-top: var(--border-w) solid var(--line-glass);
}

.replyFoot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.detailEmpty {
  display: grid;
  place-items: center;
  padding: 20px;
}

"use client";

import { Archive, File, Inbox as InboxIcon, Send, Trash2 } from "lucide-react";
import { useMemo, useState, type ReactNode } from "react";
import { Avatar } from "@/components/ui/Avatar/Avatar";
import { Badge, CountBadge } from "@/components/ui/Badge/Badge";
import { Button } from "@/components/ui/Button/Button";
import { cx } from "@/components/ui/_internal/cx";
import { EmptyState } from "@/components/ui/EmptyState/EmptyState";
import { IconButton } from "@/components/ui/IconButton/IconButton";
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from "@/components/ui/Resizable/Resizable";
import { SearchField } from "@/components/ui/SearchField/SearchField";
import { Switch } from "@/components/ui/Switch/Switch";
import { SegmentedControl } from "@/components/ui/Tabs/Tabs";
import { Textarea } from "@/components/ui/Textarea/Textarea";
import { useToast } from "@/components/ui/Toast/Toast";
import { FOLDERS, MESSAGES, type Folder, type Message } from "./data";
import styles from "./Inbox.module.css";

const ICONS: Record<Folder, ReactNode> = {
  inbox: <InboxIcon size={16} aria-hidden="true" />,
  drafts: <File size={16} aria-hidden="true" />,
  sent: <Send size={16} aria-hidden="true" />,
  archive: <Archive size={16} aria-hidden="true" />,
  trash: <Trash2 size={16} aria-hidden="true" />,
};

export type InboxProps = {
  /** Fill the parent instead of the viewport. */
  contained?: boolean;
};

/**
 * Inbox block: a mail-style app in three resizable panes. Folders on the
 * left, the message list with search and an All / Unread switch in the
 * middle, and the open message with a reply box on the right. Drop it at
 * app/inbox.
 */
export default function Inbox({ contained }: InboxProps) {
  const toast = useToast();
  const [messages, setMessages] = useState(() => MESSAGES.map((m) => (m.id === "m1" ? { ...m, unread: false } : m)));
  const [folder, setFolder] = useState<Folder>("inbox");
  const [view, setView] = useState<"all" | "unread">("all");
  const [query, setQuery] = useState("");
  const [openId, setOpenId] = useState<string | null>("m1");
  const [reply, setReply] = useState("");
  const [mute, setMute] = useState(false);

  const list = useMemo(() => {
    const q = query.trim().toLowerCase();
    return messages.filter(
      (m) =>
        m.folder === folder &&
        (view === "all" || m.unread) &&
        (!q || m.from.toLowerCase().includes(q) || m.subject.toLowerCase().includes(q) || m.preview.toLowerCase().includes(q)),
    );
  }, [messages, folder, view, query]);

  const open = messages.find((m) => m.id === openId) ?? null;
  const unreadIn = (f: Folder) => messages.filter((m) => m.folder === f && m.unread).length;

  const select = (m: Message) => {
    setOpenId(m.id);
    setMessages((all) => all.map((x) => (x.id === m.id ? { ...x, unread: false } : x)));
  };
  const moveTo = (to: Folder) => {
    if (!open) return;
    setMessages((all) => all.map((x) => (x.id === open.id ? { ...x, folder: to } : x)));
    setOpenId(null);
    toast.success(to === "archive" ? "Archived" : "Moved to trash");
  };

  return (
    <div className={cx(styles.root, contained && styles.contained)}>
      <ResizablePanelGroup height="100%" className={styles.group}>
        <ResizablePanel defaultSize={20} minSize={14}>
          <nav aria-label="Mail folders" className={styles.folders}>
            <p className={styles.brand}>
              <span className={styles.glyph} aria-hidden="true">
                A
              </span>
              Acme Mail
            </p>
            <ul className={styles.folderList}>
              {FOLDERS.map((f) => (
                <li key={f.id}>
                  <button type="button" className={styles.folder} aria-current={folder === f.id ? "page" : undefined} onClick={() => setFolder(f.id)}>
                    {ICONS[f.id]}
                    <span className={styles.folderLabel}>{f.label}</span>
                    {unreadIn(f.id) ? <CountBadge count={unreadIn(f.id)} label={`${unreadIn(f.id)} unread`} /> : null}
                  </button>
                </li>
              ))}
            </ul>
          </nav>
        </ResizablePanel>
        <ResizableHandle aria-label="Resize folders" />
        <ResizablePanel defaultSize={36} minSize={24}>
          <section aria-label="Messages" className={styles.listPane}>
            <div className={styles.listHead}>
              <h2 className={styles.h2}>{FOLDERS.find((f) => f.id === folder)?.label}</h2>
              <SegmentedControl
                aria-label="Show"
                size="sm"
                value={view}
                onChange={setView}
                options={[
                  { value: "all", label: "All" },
                  { value: "unread", label: "Unread" },
                ]}
              />
            </div>
            <div className={styles.search}>
              <SearchField aria-label="Search mail" size="sm" value={query} onValueChange={setQuery} placeholder="Search mail" />
            </div>
            <ul className={styles.messages}>
              {list.map((m) => (
                <li key={m.id}>
                  <button type="button" className={styles.message} aria-current={openId === m.id ? "true" : undefined} onClick={() => select(m)}>
                    <span className={styles.messageTop}>
                      <span className={cx(styles.from, m.unread && styles.unread)}>
                        {m.unread ? <span className={styles.dot} aria-label="Unread" /> : null}
                        {m.from}
                      </span>
                      <span className={styles.date}>{m.date}</span>
                    </span>
                    <span className={styles.subject}>{m.subject}</span>
                    <span className={styles.preview}>{m.preview}</span>
                    {m.label ? (
                      <span>
                        <Badge tone={m.label === "Billing" ? "warning" : m.label === "Team" ? "info" : "neutral"}>{m.label}</Badge>
                      </span>
                    ) : null}
                  </button>
                </li>
              ))}
            </ul>
            {list.length === 0 ? <EmptyState compact title="Nothing here" description={query ? "No messages match your search." : "This folder is empty."} /> : null}
          </section>
        </ResizablePanel>
        <ResizableHandle aria-label="Resize message list" />
        <ResizablePanel defaultSize={44} minSize={28}>
          {open ? (
            <article aria-label={open.subject} className={styles.detail}>
              <div className={styles.toolbar}>
                <IconButton label="Archive" icon={<Archive size={16} />} onClick={() => moveTo("archive")} />
                <IconButton label="Move to trash" icon={<Trash2 size={16} />} onClick={() => moveTo("trash")} />
              </div>
              <header className={styles.detailHead}>
                <Avatar name={open.from} tone="neutral" />
                <div className={styles.detailMeta}>
                  <p className={styles.detailFrom}>{open.from}</p>
                  <p className={styles.detailEmail}>{open.email}</p>
                </div>
                <span className={styles.date}>{open.date}</span>
              </header>
              <h3 className={styles.detailSubject}>{open.subject}</h3>
              <div className={styles.body}>
                {open.body.map((p, i) => (
                  <p key={i}>{p}</p>
                ))}
              </div>
              <form
                className={styles.reply}
                onSubmit={(e) => {
                  e.preventDefault();
                  setReply("");
                  toast.success("Reply sent", { description: `To ${open.from}` });
                }}
              >
                <Textarea aria-label={`Reply to ${open.from}`} rows={3} value={reply} onChange={(e) => setReply(e.target.value)} placeholder={`Reply to ${open.from}`} />
                <div className={styles.replyFoot}>
                  <Switch label="Mute this thread" checked={mute} onChange={setMute} />
                  <Button type="submit" size="sm" disabled={!reply.trim()}>
                    Send
                  </Button>
                </div>
              </form>
            </article>
          ) : (
            <div className={styles.detailEmpty}>
              <EmptyState compact title="No message open" description="Pick a message from the list to read it here." />
            </div>
          )}
        </ResizablePanel>
      </ResizablePanelGroup>
    </div>
  );
}

import Inbox from "@/components/blocks/inbox";

export default function Page() {
  return <Inbox />;
}
